24	type CompanyUserRow = {
25	  id: string;
26	  principalId: string;
27	  status: string;
28	  membershipRole: string | null;
29	  createdAt: Date;
30	  userId: string | null;
31	  name: string | null;
32	  email: string | null;
33	  image: string | null;
34	};
