42	function slugifyUserPart(value: string | null | undefined) {
43	  const normalized = value
44	    ?.trim()
45	    .toLowerCase()
46	    .replace(/['"]/g, "")
47	    .replace(/[^a-z0-9]+/g, "-")
48	    .replace(/^-+|-+$/g, "");
49	  return normalized || null;
50	}
51	
52	function userSlugCandidates(row: CompanyUserRow) {
53	  const candidates = new Set<string>();
54	  const add = (value: string | null | undefined) => {
55	    const slug = slugifyUserPart(value);
56	    if (slug) candidates.add(slug);
57	  };
58	  add(row.name);
59	  add(row.email?.split("@")[0]);
60	  add(row.email);
61	  add(row.principalId);
62	  return [...candidates];
63	}
