65	async function resolveCompanyUser(db: Db, companyId: string, rawSlug: string): Promise<CompanyUserRow | null> {
66	  const slug = slugifyUserPart(rawSlug);
67	  if (!slug) return null;
68	
69	  const rows = await db
70	    .select({
71	      id: companyMemberships.id,
72	      principalId: companyMemberships.principalId,
73	      status: companyMemberships.status,
74	      membershipRole: companyMemberships.membershipRole,
75	      createdAt: companyMemberships.createdAt,
76	      userId: authUsers.id,
77	      name: authUsers.name,
78	      email: authUsers.email,
79	      image: authUsers.image,
80	    })
81	    .from(companyMemberships)
82	    .leftJoin(authUsers, eq(authUsers.id, companyMemberships.principalId))
83	    .where(
84	      and(
85	        eq(companyMemberships.companyId, companyId),
86	        eq(companyMemberships.principalType, "user"),
87	      ),
88	    )
89	    .orderBy(desc(companyMemberships.updatedAt))
90	    .limit(200);
91	
92	  return rows.find((row) => userSlugCandidates(row).includes(slug)) ?? null;
93	}
