95	function userIssueInvolvementSql(companyId: string, userId: string) {
96	  return sql<boolean>`
97	    (
98	      ${issues.createdByUserId} = ${userId}
99	      OR ${issues.assigneeUserId} = ${userId}
100	      OR EXISTS (
101	        SELECT 1
102	        FROM ${issueComments}
103	        WHERE ${issueComments.companyId} = ${companyId}
104	          AND ${issueComments.issueId} = ${issues.id}
105	          AND ${issueComments.authorUserId} = ${userId}
106	      )
107	    )
108	  `;
109	}
110	
111	function windowStart(days: number | null) {
112	  if (!days) return null;
113	  return new Date(Date.now() - days * 24 * 60 * 60 * 1000);
114	}
115	
116	function startOfUtcDay(date: Date) {
117	  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
118	}
119	
120	function isoDay(date: Date) {
121	  return startOfUtcDay(date).toISOString().slice(0, 10);
122	}
123	
124	function dayKeyExpr(dateSql: ReturnType<typeof sql>) {
125	  return sql<string>`to_char(date_trunc('day', ${dateSql}), 'YYYY-MM-DD')`;
126	}
127	
128	function sumNumber(column: typeof costEvents.costCents | typeof costEvents.inputTokens | typeof costEvents.cachedInputTokens | typeof costEvents.outputTokens) {
129	  return sql<number>`coalesce(sum(${column}), 0)::double precision`;
130	}
