132	async function loadWindowStats(
133	  db: Db,
134	  companyId: string,
135	  userId: string,
136	  key: UserProfileWindowStats["key"],
137	  label: string,
138	  from: Date | null,
139	): Promise<UserProfileWindowStats> {
140	  const involvement = userIssueInvolvementSql(companyId, userId);
141	  const openStatuses = ["backlog", "todo", "in_progress", "in_review", "blocked"];
142	  const fromIso = from?.toISOString();
143	
144	  const [issueStats] = await db
145	    .select({
146	      touchedIssues: sql<number>`count(distinct case when ${involvement} ${fromIso ? sql`and ${issues.updatedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
147	      createdIssues: sql<number>`count(distinct case when ${issues.createdByUserId} = ${userId} ${fromIso ? sql`and ${issues.createdAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
148	      completedIssues: sql<number>`count(distinct case when ${involvement} and ${issues.status} = 'done' ${fromIso ? sql`and ${issues.completedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
149	      assignedOpenIssues: sql<number>`count(distinct case when ${issues.assigneeUserId} = ${userId} and ${issues.status} in (${sql.join(openStatuses.map((status) => sql`${status}`), sql`, `)}) then ${issues.id} end)::int`,
150	    })
151	    .from(issues)
152	    .where(and(eq(issues.companyId, companyId), isNull(issues.hiddenAt)));
153	
154	  const commentConditions = [
155	    eq(issueComments.companyId, companyId),
156	    eq(issueComments.authorUserId, userId),
157	  ];
158	  if (from) commentConditions.push(gte(issueComments.createdAt, from));
159	  const [commentStats] = await db
160	    .select({ count: sql<number>`count(*)::int` })
161	    .from(issueComments)
162	    .where(and(...commentConditions));
163	
164	  const activityConditions = [
165	    eq(activityLog.companyId, companyId),
166	    eq(activityLog.actorType, "user"),
167	    eq(activityLog.actorId, userId),
168	  ];
169	  if (from) activityConditions.push(gte(activityLog.createdAt, from));
170	  const [activityStats] = await db
171	    .select({ count: sql<number>`count(*)::int` })
172	    .from(activityLog)
173	    .where(and(...activityConditions));
174	
175	  const costConditions = [
176	    eq(costEvents.companyId, companyId),
177	    userIssueInvolvementSql(companyId, userId),
178	  ];
179	  if (from) costConditions.push(gte(costEvents.occurredAt, from));
180	  const [costStats] = await db
181	    .select({
182	      costCents: sumNumber(costEvents.costCents),
183	      inputTokens: sumNumber(costEvents.inputTokens),
184	      cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
185	      outputTokens: sumNumber(costEvents.outputTokens),
186	      costEventCount: sql<number>`count(${costEvents.id})::int`,
187	    })
188	    .from(costEvents)
189	    .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
190	    .where(and(...costConditions));
191	
192	  return {
193	    key,
194	    label,
195	    touchedIssues: Number(issueStats?.touchedIssues ?? 0),
196	    createdIssues: Number(issueStats?.createdIssues ?? 0),
197	    completedIssues: Number(issueStats?.completedIssues ?? 0),
198	    assignedOpenIssues: Number(issueStats?.assignedOpenIssues ?? 0),
199	    commentCount: Number(commentStats?.count ?? 0),
200	    activityCount: Number(activityStats?.count ?? 0),
201	    costCents: Number(costStats?.costCents ?? 0),
202	    inputTokens: Number(costStats?.inputTokens ?? 0),
203	    cachedInputTokens: Number(costStats?.cachedInputTokens ?? 0),
204	    outputTokens: Number(costStats?.outputTokens ?? 0),
205	    costEventCount: Number(costStats?.costEventCount ?? 0),
206	  };
207	}
