209	async function loadDailyStats(db: Db, companyId: string, userId: string): Promise<UserProfileDailyPoint[]> {
210	  const firstDay = startOfUtcDay(new Date(Date.now() - 13 * 24 * 60 * 60 * 1000));
211	  const points = new Map<string, UserProfileDailyPoint>();
212	  for (let index = 0; index < 14; index += 1) {
213	    const date = new Date(firstDay.getTime() + index * 24 * 60 * 60 * 1000);
214	    points.set(isoDay(date), {
215	      date: isoDay(date),
216	      activityCount: 0,
217	      completedIssues: 0,
218	      costCents: 0,
219	      inputTokens: 0,
220	      cachedInputTokens: 0,
221	      outputTokens: 0,
222	    });
223	  }
224	
225	  const activityDay = dayKeyExpr(sql`${activityLog.createdAt}`);
226	  const activityRows = await db
227	    .select({
228	      date: activityDay,
229	      count: sql<number>`count(*)::int`,
230	    })
231	    .from(activityLog)
232	    .where(
233	      and(
234	        eq(activityLog.companyId, companyId),
235	        eq(activityLog.actorType, "user"),
236	        eq(activityLog.actorId, userId),
237	        gte(activityLog.createdAt, firstDay),
238	      ),
239	    )
240	    .groupBy(activityDay);
241	
242	  for (const row of activityRows) {
243	    const point = points.get(row.date);
244	    if (point) point.activityCount = Number(row.count);
245	  }
246	
247	  const completedDay = dayKeyExpr(sql`${issues.completedAt}`);
248	  const completedRows = await db
249	    .select({
250	      date: completedDay,
251	      count: sql<number>`count(distinct ${issues.id})::int`,
252	    })
253	    .from(issues)
254	    .where(
255	      and(
256	        eq(issues.companyId, companyId),
257	        isNull(issues.hiddenAt),
258	        eq(issues.status, "done"),
259	        gte(issues.completedAt, firstDay),
260	        userIssueInvolvementSql(companyId, userId),
261	      ),
262	    )
263	    .groupBy(completedDay);
264	
265	  for (const row of completedRows) {
266	    const point = points.get(row.date);
267	    if (point) point.completedIssues = Number(row.count);
268	  }
269	
270	  const costDay = dayKeyExpr(sql`${costEvents.occurredAt}`);
271	  const costRows = await db
272	    .select({
273	      date: costDay,
274	      costCents: sumNumber(costEvents.costCents),
275	      inputTokens: sumNumber(costEvents.inputTokens),
276	      cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
277	      outputTokens: sumNumber(costEvents.outputTokens),
278	    })
279	    .from(costEvents)
280	    .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
281	    .where(
282	      and(
283	        eq(costEvents.companyId, companyId),
284	        gte(costEvents.occurredAt, firstDay),
285	        userIssueInvolvementSql(companyId, userId),
286	      ),
287	    )
288	    .groupBy(costDay);
289	
290	  for (const row of costRows) {
291	    const point = points.get(row.date);
292	    if (!point) continue;
293	    point.costCents = Number(row.costCents);
294	    point.inputTokens = Number(row.inputTokens);
295	    point.cachedInputTokens = Number(row.cachedInputTokens);
296	    point.outputTokens = Number(row.outputTokens);
297	  }
298	
299	  return [...points.values()];
300	}
