302	/** Minimal company access check using fields available on ActorContext. */
303	function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
304	  if (!ctx.actor) throw unauthorized();
305	  // Agent actors carry a single companyId — reject cross-tenant access.
306	  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
307	    throw forbidden("Agent key cannot access another company");
308	  }
309	  // Board actor company-list enforcement is handled by the Express auth
310	  // middleware before the Handler is reached, so no further check is needed
311	  // here. TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
312	}
