314	function buildHandlers(db: Db) {
315	  // server/src/routes/user-profiles.ts:303
316	  const getUserProfile: Handler = async (ctx) => {
317	    const companyId = ctx.param("companyId") ?? "";
318	    const userSlug = ctx.param("userSlug") ?? "";
319	    assertCompanyAccessCtx(ctx, companyId);
320	
321	    const row = await resolveCompanyUser(db, companyId, userSlug);
322	    if (!row) throw notFound("User not found");
323	    const canonicalSlug = userSlugCandidates(row)[0] ?? row.principalId;
324	    const userId = row.userId ?? row.principalId;
325	
326	    const [stats, daily, recentIssues, recentActivity, topAgents, topProviders] = await Promise.all([
327	      Promise.all(
328	        PROFILE_WINDOWS.map((entry) =>
329	          loadWindowStats(db, companyId, userId, entry.key, entry.label, windowStart(entry.days)),
330	        ),
331	      ),
332	      loadDailyStats(db, companyId, userId),
333	      db
334	        .select({
335	          id: issues.id,
336	          identifier: issues.identifier,
337	          title: issues.title,
338	          status: issues.status,
339	          priority: issues.priority,
340	          assigneeAgentId: issues.assigneeAgentId,
341	          assigneeUserId: issues.assigneeUserId,
342	          updatedAt: issues.updatedAt,
343	          completedAt: issues.completedAt,
344	        })
345	        .from(issues)
346	        .where(
347	          and(
348	            eq(issues.companyId, companyId),
349	            isNull(issues.hiddenAt),
350	            userIssueInvolvementSql(companyId, userId),
351	          ),
352	        )
353	        .orderBy(desc(issues.updatedAt))
354	        .limit(8),
355	      db
356	        .select({
357	          id: activityLog.id,
358	          action: activityLog.action,
359	          entityType: activityLog.entityType,
360	          entityId: activityLog.entityId,
361	          details: activityLog.details,
362	          createdAt: activityLog.createdAt,
363	        })
364	        .from(activityLog)
365	        .where(
366	          and(
367	            eq(activityLog.companyId, companyId),
368	            eq(activityLog.actorType, "user"),
369	            eq(activityLog.actorId, userId),
370	          ),
371	        )
372	        .orderBy(desc(activityLog.createdAt))
373	        .limit(12),
374	      db
375	        .select({
376	          agentId: costEvents.agentId,
377	          agentName: agents.name,
378	          costCents: sumNumber(costEvents.costCents),
379	          inputTokens: sumNumber(costEvents.inputTokens),
380	          cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
381	          outputTokens: sumNumber(costEvents.outputTokens),
382	        })
383	        .from(costEvents)
384	        .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
385	        .leftJoin(agents, eq(agents.id, costEvents.agentId))
386	        .where(and(eq(costEvents.companyId, companyId), userIssueInvolvementSql(companyId, userId)))
387	        .groupBy(costEvents.agentId, agents.name)
388	        .orderBy(desc(sumNumber(costEvents.costCents)))
389	        .limit(5),
390	      db
391	        .select({
392	          provider: costEvents.provider,
393	          biller: costEvents.biller,
394	          model: costEvents.model,
395	          costCents: sumNumber(costEvents.costCents),
396	          inputTokens: sumNumber(costEvents.inputTokens),
397	          cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
398	          outputTokens: sumNumber(costEvents.outputTokens),
399	        })
400	        .from(costEvents)
401	        .innerJoin(issues, and(eq(issues.id, costEvents.issueId), eq(issues.companyId, costEvents.companyId)))
402	        .where(and(eq(costEvents.companyId, companyId), userIssueInvolvementSql(companyId, userId)))
403	        .groupBy(costEvents.provider, costEvents.biller, costEvents.model)
404	        .orderBy(desc(sumNumber(costEvents.costCents)))
405	        .limit(5),
406	    ]);
407	
408	    const user: UserProfileIdentity = {
409	      id: userId,
410	      slug: canonicalSlug,
411	      name: row.name,
412	      email: row.email,
413	      image: row.image,
414	      membershipRole: row.membershipRole,
415	      membershipStatus: row.status,
416	      joinedAt: row.createdAt,
417	    };
418	
419	    const payload: UserProfileResponse = {
420	      user,
421	      stats,
422	      daily,
423	      recentIssues: recentIssues.map((issue) => ({
424	        ...issue,
425	        status: issue.status as UserProfileResponse["recentIssues"][number]["status"],
426	        priority: issue.priority as UserProfileResponse["recentIssues"][number]["priority"],
427	      })),
428	      recentActivity,
429	      topAgents: topAgents.map((entry) => ({
430	        ...entry,
431	        costCents: Number(entry.costCents),
432	        inputTokens: Number(entry.inputTokens),
433	        cachedInputTokens: Number(entry.cachedInputTokens),
434	        outputTokens: Number(entry.outputTokens),
435	      })),
436	      topProviders: topProviders.map((entry) => ({
437	        ...entry,
438	        costCents: Number(entry.costCents),
439	        inputTokens: Number(entry.inputTokens),
440	        cachedInputTokens: Number(entry.cachedInputTokens),
441	        outputTokens: Number(entry.outputTokens),
442	      })),
443	    };
444	
445	    return Response.json(payload);
446	  };
447	
448	  return { getUserProfile };
449	}
