451	export function userProfileRoutes(db: Db) {
452	  const router = Router();
453	  const { getUserProfile } = buildHandlers(db);
454	
455	  const storageSentinel = new Proxy({} as StorageService, {
456	    get(_target, prop) {
457	      throw new Error(`userProfile handler unexpectedly accessed storage.${String(prop)}`);
458	    },
459	  });
460	  const deps = { db, storage: storageSentinel };
461	
462	  router.get("/companies/:companyId/users/:userSlug/profile", expressHandler(getUserProfile, deps));
463	
464	  return router;
465	}
